d = sys.stdin.read().split()
r, c = int(d[0]), int(d[1])
g = d[2:2 + r]
w = d[2 + r]
res = []
for i in range(r):
    for j in range(c):
        ok = False
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                if di == 0 and dj == 0:
                    continue
                s = ''
                a, b = i, j
                while 0 <= a < r and 0 <= b < c and len(s) < len(w):
                    s += g[a][b]
                    a += di
                    b += dj
                if s == w:
                    ok = True
        if ok:
            res.append((i, j))
if res:
    for i, j in res:
        print(i, j)
else:
    print(-1)

